<script setup>
import { onMounted, ref } from 'vue'
import { apiGet, apiRequest } from '../services/api.js'
import { label } from '../utils.js'
const appointments = ref([]), urls = ref({}), access = ref({}), error = ref(''), notice = ref(''), busy = ref(false)
async function save(a) { busy.value = true; error.value = ''; try { await apiRequest(`/appointments/${a.id}/access`, 'PUT', { meeting_url: urls.value[a.id] || '' }); urls.value[a.id] = ''; notice.value = 'Link guardado com acesso restrito. Não será exibido à gestão empresarial.' } catch (e) { error.value = e.message } finally { busy.value = false } }
async function enter(a) { error.value = ''; try { access.value[a.id] = (await apiGet(`/appointments/${a.id}/access`)).meeting_url } catch (e) { error.value = e.message } }
onMounted(async () => { busy.value = true; try { appointments.value = await apiGet('/professional/appointments') } catch (e) { error.value = e.message } finally { busy.value = false } })
</script>
<template><p class="eyebrow">MINHA AGENDA ASSISTENCIAL</p><h1>Atendimentos presenciais e teleconsultas</h1><p class="text-secondary">Seus pacientes vinculados, dos últimos sete dias aos próximos noventa dias.</p><p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="notice" class="alert alert-success" role="status">{{ notice }}</p><p v-if="busy">Processando…</p><p v-if="!busy && !appointments.length">Nenhum atendimento neste período.</p><div class="row g-4"><div v-for="a in appointments" :key="a.id" class="col-lg-6"><article class="card card-body h-100"><h2 class="h5"><RouterLink :to="`/patients/${a.patient_id}`">{{ a.patient_name }}</RouterLink></h2><p>{{ a.scheduled_at }} · {{ a.modality === 'telehealth' ? 'Teleconsulta' : 'Presencial' }} · {{ label(a.status) }}<br><small>{{ a.service_unit }}</small></p><template v-if="a.modality === 'telehealth' && ['confirmed', 'expected'].includes(a.status)"><form @submit.prevent="save(a)"><label :for="`room-${a.id}`" class="form-label">Link HTTPS exclusivo desta teleconsulta</label><input :id="`room-${a.id}`" v-model="urls[a.id]" class="form-control mb-2" type="url" required maxlength="2000" placeholder="https://seu-provedor/sala"><button class="btn btn-success" :disabled="busy">Guardar link restrito</button></form><p class="small text-secondary mt-3">Use o provedor autorizado pela instituição. A plataforma organiza o acesso; a chamada acontece no provedor informado.</p><button class="btn btn-outline-success align-self-start" @click="enter(a)">Consultar acesso à sala</button><a v-if="access[a.id]" :href="access[a.id]" target="_blank" rel="noopener noreferrer" class="btn btn-success mt-2">Entrar na sala</a></template></article></div></div></template>
